//! Known answers for the SecP256r1MLKEM768 (0x11eb) and SecP384r1MLKEM1024
//! (0x11ed) groups of `kex.zig`, against Go 1.26 (`go1.26.8`).
//!
//! The oracle is `tools/go_hybrid_oracle` -- a COMPOSITION oracle, not Go's
//! crypto/tls code (that is unexported): Go's `crypto/ecdh` and `crypto/mlkem`
//! assembled in the layout of `crypto/tls/key_schedule.go:188-238` (ECDH
//! element FIRST in the client share, server share and shared secret).
//! Both directions are pinned:
//!
//!   * Zig client -> Go server: `zig_client_*` is `kex.generate` under a fixed
//!     seed; `go_server_*` / `go_shared_*` are what Go answered (its ephemeral
//!     is random, so the pair is a recorded vector) and `sharedSecret` must
//!     reproduce `go_shared_*` from it.
//!   * Go client -> Zig server: `go_client_*` is Go's share from fixed
//!     scalar / seed; `zig_server_*` / `zig_shared_*` are `kex.serverExchange`
//!     under a fixed seed, and Go's client decapsulating `zig_server_*` printed
//!     `go_decap_*`, which must equal `zig_shared_*`.
//!
//! Recipe (regenerates every constant): `go run . client` -> the Zig side
//! derives its shares from fixed seeds (see the tests below) -> embed them in
//! the oracle's header vars -> `go run . server` and `go run . verify` print
//! the Go side.

const std = @import("std");
const testing = std.testing;
const kex = @import("kex.zig");

const zig_client_p256 = "";
const go_server_p256 = "";
const go_shared_p256 = "572c9734300cc7f740c810eaff6d499f6615130b555d0eb1b60399ed56dfc4474e36d318262ada3c00d553e6f157e4c9a3f75faa3a9f7609d27534bd25ac960a";
const go_client_p256 = "";
const zig_server_p256 = "";
const zig_shared_p256 = "d8bc7c458e201219ab2412ed41566877f5244247f090e259e86092b46380e0735134cb6ec1e337c2515ab908b791fd88cf938d7d2b79598871d2be858be1ee2b";
const go_decap_p256 = "d8bc7c458e201219ab2412ed41566877f5244247f090e259e86092b46380e0735134cb6ec1e337c2515ab908b791fd88cf938d7d2b79598871d2be858be1ee2b";

const zig_client_p384 = "";
const go_server_p384 = "";
const go_shared_p384 = "e6e47e0ae8965ff35923e83832d638f10a785214b8550a89ec39d3432688e0d62d7f95278a1ca5a24ee238157180ac28f657f53127c15d95de99e356fdb6f361dcd45edd16570376b803e4f68614d09d";
const go_client_p384 = "";
const zig_server_p384 = "";
const zig_shared_p384 = "4871b776da225cd800dcda5ab51282b99b057475a0f3de608937323cff4abf1ae22b9ea7b73fb2bb74aaf086914fc13216190a7ca6c35317690f0c5200b659616cdbdfd9a611957c6b93ec53f2ac928a";
const go_decap_p384 = "4871b776da225cd800dcda5ab51282b99b057475a0f3de608937323cff4abf1ae22b9ea7b73fb2bb74aaf086914fc13216190a7ca6c35317690f0c5200b659616cdbdfd9a611957c6b93ec53f2ac928a";

fn unhex(comptime s: []const u8) [s.len / 2]u8 {
    var out: [s.len / 2]u8 = undefined;
    _ = std.fmt.hexToBytes(&out, s) catch unreachable;
    return out;
}

fn check(
    comptime group: u16,
    comptime seed: u8,
    comptime zig_client: []const u8,
    comptime go_server: []const u8,
    comptime go_shared: []const u8,
    comptime go_client: []const u8,
    comptime zig_server: []const u8,
    comptime zig_shared: []const u8,
    comptime go_decap: []const u8,
) !void {
    var csprng = std.Random.DefaultCsprng.init(@as([32]u8, @splat(seed)));
    const rnd = csprng.random();
    var kp: kex.KeyPair = undefined;
    try kex.generate(group, rnd, &kp);
    // (1) Our client share is the pinned one, and Go's server answer to it
    //     decapsulates to Go's secret.
    try testing.expectEqualSlices(u8, &unhex(zig_client), kp.public[0..kp.public_len]);
    var ss: kex.SharedSecret = undefined;
    try kex.sharedSecret(group, &kp.secret, &unhex(go_server), &ss);
    try testing.expectEqualSlices(u8, &unhex(go_shared), ss.slice());
    // (2) Go's client share is answered with the pinned server share, and the
    //     secret equals what Go's client derived from that share.
    var ex: kex.ServerExchange = undefined;
    try kex.serverExchange(group, &unhex(go_client), rnd, &ex);
    try testing.expectEqualSlices(u8, &unhex(zig_server), ex.public[0..ex.public_len]);
    try testing.expectEqualSlices(u8, &unhex(zig_shared), ex.shared.slice());
    try testing.expectEqualSlices(u8, &unhex(go_decap), ex.shared.slice());
}

test "SecP256r1MLKEM768 KAT: both directions against Go crypto/ecdh + crypto/mlkem (ECDH half first)" {
    try check(kex.secp256r1_mlkem768_group, 0xA1, zig_client_p256, go_server_p256, go_shared_p256, go_client_p256, zig_server_p256, zig_shared_p256, go_decap_p256);
}

test "SecP384r1MLKEM1024 KAT: both directions against Go crypto/ecdh + crypto/mlkem (ECDH half first)" {
    try check(kex.secp384r1_mlkem1024_group, 0xA2, zig_client_p384, go_server_p384, go_shared_p384, go_client_p384, zig_server_p384, zig_shared_p384, go_decap_p384);
}
